1	import { motion, type HTMLMotionProps } from "framer-motion";
2	import { forwardRef } from "react";
3	
4	interface FadeInProps extends HTMLMotionProps<"div"> {
5	  delay?: number;
6	  duration?: number;
7	  direction?: "up" | "down" | "left" | "right" | "none";
8	  distance?: number;
9	}
10	
11	const directionMap = {
12	  up: { y: 1, x: 0 },
13	  down: { y: -1, x: 0 },
14	  left: { x: 1, y: 0 },
15	  right: { x: -1, y: 0 },
16	  none: { x: 0, y: 0 },
17	};
18	
19	const FadeIn = forwardRef<HTMLDivElement, FadeInProps>(
20	  ({ delay = 0, duration = 0.25, direction = "up", distance = 10, children, ...props }, ref) => {
21	    const dir = directionMap[direction];
22	    return (
23	      <motion.div
24	        ref={ref}
25	        initial={{ opacity: 0, x: dir.x * distance, y: dir.y * distance }}
26	        animate={{ opacity: 1, x: 0, y: 0 }}
27	        transition={{ duration, delay, ease: "easeOut" }}
28	        {...props}
29	      >
30	        {children}
31	      </motion.div>
32	    );
33	  }
34	);
35	FadeIn.displayName = "FadeIn";
36	
37	export { FadeIn };
