40	function hasAllowedExtension(filename: string): boolean {
41	  const lower = filename.toLowerCase();
42	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
43	}
44	
45	interface JobInfo {
46	  id: string;
47	  title: string;
48	  status: string;
49	  job_description: string;
50	}
51	
52	type FormFieldType =
53	  | "text"
54	  | "number"
55	  | "select"
56	  | "multiselect"
57	  | "date"
58	  | "url"
59	  | "textarea"
60	  | "checkbox";
61	
62	interface JobFormField {
63	  id: string;
64	  field_type: FormFieldType;
65	  label: string;
66	  placeholder: string | null;
67	  required: boolean;
68	  options: string[] | null;
69	  sort_order: number;
70	}
