261	  }
262	
263	  // ── Job not found ───────────────────────────────────────────────────────
264	  // Note: status === "failed" means the ranking pipeline failed, NOT that the
265	  // job is closed for applications. We don't block applications on failed jobs.
266	  if (!jobLoading && (jobError || !job)) {
267	    return (
268	      <div className="min-h-screen bg-background flex flex-col">
269	        <ApplyHeader />
